WITH sales_agg AS (SELECT ss.ss_hdemo_sk AS hd_demo_sk, SUM(ss.ss_ext_sales_price) AS sales_amount, SUM(ss.ss_quantity) AS units_sold FROM store_sales ss GROUP BY ss.ss_hdemo_sk), returns_agg AS (SELECT sr.sr_hdemo_sk AS hd_demo_sk, SUM(sr.sr_return_amt) AS returns_amount, SUM(sr.sr_return_quantity) AS units_returned FROM store_returns sr GROUP BY sr.sr_hdemo_sk), combined AS (SELECT sa.hd_demo_sk, sa.sales_amount, ra.returns_amount, CASE WHEN sa.sales_amount = 0 THEN 0 ELSE ra.returns_amount / sa.sales_amount END AS return_ratio FROM sales_agg sa LEFT JOIN returns_agg ra ON sa.hd_demo_sk = ra.hd_demo_sk) SELECT c.hd_demo_sk, ib.ib_lower_bound, ib.ib_upper_bound, c.sales_amount, c.returns_amount, c.return_ratio, CASE WHEN c.return_ratio > 0.5 THEN 'High Return Ratio' WHEN c.return_ratio > 0.2 THEN 'Medium Return Ratio' ELSE 'Low Return Ratio' END AS ratio_category, PERCENT_RANK() OVER (ORDER BY c.return_ratio DESC) AS return_ratio_percentile, DENSE_RANK() OVER (ORDER BY c.return_ratio DESC) AS return_ratio_rank FROM combined c JOIN household_demographics hd ON c.hd_demo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk ORDER BY return_ratio_rank LIMIT 50
